 let editorSettings=null;let ctx,selected=null,stages=['all'],statusPicker=null,configuredInitial=null,inspectorTab='summary',editing=null,editorVersion=0,editorFee=0,busy=false,dialogOrder=null;
 function el(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e}
