 function visible(){if(!ctx)return [];const q=$('#order-search').value.toLocaleLowerCase('pt-BR'),mode=$('#order-type').value,day=$('#order-date').value;return ctx.getOrders().filter(o=>stages.some(key=>matchesTab(o,key))&&(mode==='all'||mode===o.fulfillment)&&(!day||o.date===day)&&`${o.id} ${o.customer} ${o.recipient} ${o.phone} ${o.city||''}`.toLocaleLowerCase('pt-BR').includes(q)).sort(OrderCollection.compare);}
