 async function copyText(value){if(navigator.clipboard?.writeText){try{await navigator.clipboard.writeText(value);return;}catch{}}const active=document.activeElement,field=el('textarea');field.value=value;field.setAttribute('aria-hidden','true');field.style.cssText='position:fixed;left:-10000px;top:0';document.body.append(field);try{field.select();if(!document.execCommand('copy'))throw Error('Cópia indisponível');}finally{field.remove();if(active?.isConnected)active.focus({preventScroll:true});}}
