   const section=el('section',undefined,'inspector-section order-destination-card'),fold=el('details',undefined,'order-pickup-details'),summary=el('summary');summary.append(UIIcons.label('store','Local de retirada'),UIIcons.icon('chevronDown'));fold.append(summary);const address=o.pickupLocation?PickupLocations.format(o.pickupLocation):(ctx.getSettings?.().pickupAddress||'Confirme o endereço de retirada com a loja');fold.append(el('p',address),link('Ver endereço no mapa','https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(address)));if(o.pickupLocation?.instructions)fold.append(el('p',o.pickupLocation.instructions,'small'));section.append(fold);return section;
