  const openAddresses=()=>{if(!chosen||loading)return;DeliveryAddressBook.open({customer:chosen,selectedId:destination?.id||o.deliveryAddress?.id,orderContext:key==='address'?true:'preview',onSelected:address=>{if(!form.isConnected)return;destination=address;message.textContent=key==='address'?'Atualizando endereço e destinatário no pedido…':'Confira o destinatário e o endereço antes de salvar.';show();if(key==='address')form.requestSubmit();},onCancel:()=>{if(form.isConnected)valid();}});};
