  let settings=null,destination=null,customer=null,quote=null,sequence=0,controller=null,saving=false;
  const field=(name,label,choices)=>{const wrap=el('label',label),input=el(choices?'select':'input');input.name=name;input.setAttribute('aria-label',label);if(choices)for(const [value,text]of choices)input.append(new Option(text,value));else input.type='date';input.value=o[name]||'';wrap.append(input);form.append(wrap);return input;};
  const mode=field('fulfillment','Modalidade',[['pickup','Retirada'],['delivery','Entrega'],['store','Venda Loja']]),timing=field('scheduleMode','Tipo de agendamento',[['scheduled','Agendar'],['now','Para agora']]),day=field('date','Data'),slot=field('timeSlot','Faixa de horário',[['','Selecione o horário']]),period=el('p','','small schedule-auto-period'),pickup=field('pickupLocationId','Local de retirada',[]),address=el('div',undefined,'fulfillment-address-preview');
  const choose=button('Escolher ou cadastrar endereço',()=>openAddress(),'secondary'),totals=el('div',undefined,'fulfillment-quote'),actions=el('div',undefined,'inline-edit-actions'),save=el('button','Salvar','button'),cancel=button('Cancelar',endLine,'secondary');save.type='submit';save.disabled=true;actions.append(cancel,save);form.append(period,address,choose,totals,message,actions);row.append(form);
  const read=()=>({action:'fulfillment',version,fulfillment:mode.value,scheduleMode:timing.value,date:day.value,timeSlot:timing.value==='now'?'':slot.value,...(mode.value!==o.fulfillment&&mode.value==='pickup'&&pickup.value?{pickupLocationId:pickup.value}:{}),...(mode.value!==o.fulfillment&&mode.value==='delivery'&&destination&&customer?{customerId:customer.id,addressId:destination.id,addressVersion:destination.version}:{})});
